 Dictionary<string,object> CurrentFile(){if(table.SelectedIndices.Count==0||table.SelectedItems[0].Tag==null)return null;return json.Deserialize<Dictionary<string,object>>((string)table.SelectedItems[0].Tag);}
 string ItemCode(ListViewItem item){try{if(item.Tag==null)return "PENDING";var d=json.Deserialize<Dictionary<string,object>>((string)item.Tag);return d.ContainsKey("status")?(string)d["status"]:"PENDING";}catch{return "PENDING";}}
 Color StatusColor(string code){return code=="CHECKED_CANDIDATE_REVIEW_REQUIRED"||code=="LAYER_SPLIT_COMPLETE"?teal:code=="ERROR"||code=="BLOCKED"||code=="BLOCKED_REVIEW"?Color.FromArgb(180,57,56):code=="ISSUES_FOUND"||code=="LAYER_SPLIT_PARTIAL"?Color.FromArgb(155,99,19):muted;}
 void TranslateInterface(){if(!interfaceBuilt)return;bool ru=lang.SelectedIndex==0;workflow.Text=ru?"01  Выберите файлы    /    02  Задайте точность    /    03  Получите готовые контуры":"01  Choose files    /    02  Set precision    /    03  Get closed contours";buttons[4].Text=ru?"Обработать DXF":"Process DXF";buttons[6].Text=ru?"Папка результата":"Result folder";deviationHelp.Text=ru?"Меньше значение — точнее контур":"Smaller value means finer approximation";layerHelp.Text=ru?"Имена через запятую":"Names separated by commas";outputHelp.Text=ru?"Автоматически рядом с исходниками • без перезаписи":"Automatic source folder output • no overwrites";batchTitle.Text=ru?"ФАЙЛЫ В ОБРАБОТКЕ":"FILE QUEUE";resultTitle.Text=ru?"РЕЗУЛЬТАТ ПРОВЕРКИ":"VERIFICATION RESULT";subtitle.Text=ru?"ПОЯСНЕНИЯ":"DETAILS";string[] labels=ru?new[]{"Наруж. / отверст. / островки","Замкнутые объекты","Отклонение, мм","Исходный файл"}:new[]{"Outer / holes / islands","Closed entities","Deviation, mm","Original file"};for(int i=0;i<4;i++)metricLabels[i].Text=labels[i];var selected=CurrentFile();if(selected!=null)details.Text=ReadableDetails(Describe(selected));UpdateDashboard(selected);}
 string Number(object value){double n;return Double.TryParse(Convert.ToString(value,CultureInfo.InvariantCulture),System.Globalization.NumberStyles.Float,CultureInfo.InvariantCulture,out n)?n.ToString(n!=0&&Math.Abs(n)<.000001?"0.##E+0":"0.######",CultureInfo.CurrentCulture):"—";}
 Dictionary<string,object> Map(Dictionary<string,object> d,string key){return d!=null&&d.ContainsKey(key)?d[key] as Dictionary<string,object>:null;}
 void UpdateDashboard(Dictionary<string,object> f){if(!interfaceBuilt)return;if(busy&&!processingWatch.IsRunning)processingWatch.Restart();if(!busy)processingWatch.Stop();progress.Visible=busy;bool ru=lang.SelectedIndex==0;int done=table.Items.Cast<ListViewItem>().Count(i=>i.Tag!=null);foreach(ListViewItem row in table.Items){if(row.Tag!=null){var item=json.Deserialize<Dictionary<string,object>>((string)row.Tag);if(item.ContainsKey("status"))row.SubItems[1].Text=Friendly((string)item["status"]);if(item.ContainsKey(ru?"findingsRu":"findingsEn"))row.SubItems[2].Text=String.Join(" ",((System.Collections.IList)item[ru?"findingsRu":"findingsEn"]).Cast<object>().Select(x=>x.ToString()));}}batchCount.Text=ru?"Файлы: "+files.Count+"  ·  обработано: "+done:"Files: "+files.Count+"  ·  processed: "+done;foreach(var value in metricValues)value.Text="—";string code=f!=null&&f.ContainsKey("status")?(string)f["status"]:"PENDING";
  bool hasJob=f!=null&&f.ContainsKey("diagnosis");resultState.Text=busy?(ru?"Выполняется обработка…":"Processing…"):!hasJob?(ru?(files.Count==0?"Добавьте файлы":"Файл загружен"):(files.Count==0?"Add files":"File loaded")):code=="CHECKED_CANDIDATE_REVIEW_REQUIRED"?(ru?"Проверки пройдены":"Checks passed"):Friendly(code);resultState.ForeColor=busy?teal:StatusColor(code);resultNote.Text=busy?(ru?"Окно можно перемещать и изменять":"You can move and resize this window"):!hasJob?(ru?"Добавьте DXF или перетащите файл сюда":"Add a DXF or drop files into the window"):code=="CHECKED_CANDIDATE_REVIEW_REQUIRED"?(ru?"Перед резкой проверьте файл в CAM":"Review in your CAM system before cutting"):code=="BLOCKED_REVIEW"?(ru?"Причины и результат доступны в отчёте":"See report for reasons and candidate"):ru?"Данные выбранного файла":"Selected file information";
  var conversion=Map(f,"conversion");var topology=Map(conversion,"topologyComparison");var hierarchy=topology!=null&&topology.ContainsKey("verifiedAtJoinTolerance")&&(bool)topology["verifiedAtJoinTolerance"]?Map(topology,"outputHierarchy"):Map(f,"contourClassification");if(hierarchy!=null&&hierarchy.ContainsKey("verified")&&(bool)hierarchy["verified"]&&hierarchy.ContainsKey("outerCount"))metricValues[0].Text=hierarchy["outerCount"]+" / "+hierarchy["holeCount"]+" / "+hierarchy["islandCount"];
  var joined=Map(f,"contourJoin");if(joined!=null&&joined.ContainsKey("verified")&&(bool)joined["verified"]){metricValues[1].Text=(Convert.ToInt32(joined["closedPolylineCount"])+Convert.ToInt32(joined["preservedCircleCount"])).ToString();if(joined.ContainsKey("maximumTotalDeviationMm"))metricValues[2].Text=Number(joined["maximumTotalDeviationMm"]);}
  if(metricValues[2].Text=="—"&&conversion!=null&&conversion.ContainsKey("maximumWholeCurveBoundMm"))metricValues[2].Text=Number(conversion["maximumWholeCurveBoundMm"]);if(f!=null&&f.ContainsKey("sourceUnchanged"))metricValues[3].Text=(bool)f["sourceUnchanged"]?(ru?"Сохранён":"Preserved"):(ru?"Изменён":"Changed");
  bool ready=f!=null&&f.ContainsKey("candidate")&&File.Exists((string)f["candidate"]);openDxf.Enabled=!busy&&ready;buttons[5].Enabled=!busy&&f!=null&&f.ContainsKey("reportPath");if(!busy){string folder=ResultFolder();status.Text=folder!=null?(ru?"Результат: ":"Result: ")+folder:(ru?"Ctrl+O — добавить DXF     Ctrl+Enter — обработать     F5 — проверить":"Ctrl+O — add DXF     Ctrl+Enter — process     F5 — inspect");settingTips.SetToolTip(output,output.Text);}table.Invalidate();
 }
 void UpdateProcessingClock(){if(!busy)return;bool ru=lang.SelectedIndex==0;string elapsed=processingWatch.Elapsed.ToString(@"mm\:ss");resultNote.Text=(ru?"Прошло ":"Elapsed ")+elapsed+(ru?" • исходники сохраняются":" • originals preserved");status.Text=(ru?"Обработка DXF  ·  ":"Processing DXF  ·  ")+elapsed+(ru?"  ·  файлов: ":"  ·  files: ")+files.Count;}
 async Task ReviewSnapshot(string path){
  var job=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(path));var item=(Dictionary<string,object>)((System.Collections.IList)job["files"])[0];
  item["processedFolder"]=Directory.GetParent(Path.GetDirectoryName(path)).FullName;item["reportPath"]=Path.ChangeExtension(path,".html");
  Add(new[]{item["source"].ToString()});table.Items[0].Tag=json.Serialize(item);tol.Text=job["toleranceMm"].ToString();UpdateLocation();previewMode.SelectedIndex=1;await ShowPreview();UpdateDashboard(item);
  if(preview.Curves.Count==0||!openDxf.Enabled)throw new Exception("Real result preview failed");
  using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(root,"build","gui-real-result.png"));}
 }
 async Task CheckFileDrop(){
  string folder=Path.Combine(root,"build","drop-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string sample=Path.Combine(folder,"dropped.dxf");File.Copy(Path.Combine(root,"samples","rectangle-mm.dxf"),sample);
  int previous=files.Count;var data=new DataObject();data.SetData(DataFormats.FileDrop,new[]{folder});OnDragDrop(new DragEventArgs(data,0,0,0,DragDropEffects.Copy,DragDropEffects.Copy));
  DateTime deadline=DateTime.UtcNow.AddSeconds(15);while(!files.Contains(sample)){if(DateTime.UtcNow>deadline)throw new Exception("Folder drop discovery failed");await Task.Delay(20);}
  OnDragDrop(new DragEventArgs(data,0,0,0,DragDropEffects.Copy,DragDropEffects.Copy));await Task.Delay(250);if(files.Count!=previous+1)throw new Exception("Folder drop duplicated an input");
  int index=files.IndexOf(sample);table.Items[index].Remove();files.RemoveAt(index);UpdateDashboard(CurrentFile());
 }
