  int w=Width,h=Height,language=lang.SelectedIndex;
  foreach(int selectedLanguage in new[]{0,1}){lang.SelectedIndex=selectedLanguage;Translate();Size=new Size(1100,820);await Task.Delay(50);PerformLayout();
   foreach(var button in buttons)if(button.Right>button.Parent.ClientSize.Width||button.Bottom>button.Parent.ClientSize.Height)throw new Exception("Action clipped at minimum size: "+button.Text);
   if(table.Columns.Cast<ColumnHeader>().Sum(c=>c.Width)>table.ClientSize.Width)throw new Exception("File queue columns overflow");if(openDxf.Right>openDxf.Parent.ClientSize.Width)throw new Exception("Open DXF clipped at minimum size");
   if(preview.Width<Width*.55||preview.Height<250)throw new Exception("Preview too small at minimum window size");
   using(var image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(0,0,Width,Height));image.Save(Path.Combine(root,"build",selectedLanguage==0?"gui-minimum-ru.png":"gui-minimum-en.png"));}
  }Size=new Size(w,h);lang.SelectedIndex=language;Translate();await Task.Delay(50);
 }
 string ReadableDetails(string text){return Regex.Replace(text,@"-?\d+\.\d{9,}(?:[Ee][+-]?\d+)?",m=>Number(m.Value));}
}
